import React, { useState, useEffect } from 'react';
import axios from 'axios';
import './../assets/css/profile.css';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faUserCircle, faEnvelope, faUserTag, faCamera, faUpload } from '@fortawesome/free-solid-svg-icons';

const Profile = () => {
    const [user, setUser] = useState(null);
    const [photo, setPhoto] = useState(null);

    useEffect(() => {
        const fetchUserData = async () => {
            try {
                const token = localStorage.getItem('token');
                const res = await axios.get('http://localhost:5000/api/auth/me', {
                    headers: {
                        'x-auth-token': token
                    }
                });
                setUser(res.data);
            } catch (err) {
                console.error(err);
                alert('Failed to fetch user data.');
            }
        };

        fetchUserData();
    }, []);

    const handlePhotoChange = (e) => {
        setPhoto(e.target.files[0]);
    };

    const handlePhotoUpload = async () => {
        if (!photo) {
            alert('Please select a photo to upload.');
            return;
        }

        const formData = new FormData();
        formData.append('photo', photo);

        try {
            const token = localStorage.getItem('token');
            await axios.post('http://localhost:5000/api/auth/upload-photo', formData, {
                headers: {
                    'Content-Type': 'multipart/form-data',
                    'x-auth-token': token
                }
            });
            alert('Photo uploaded successfully!');
        } catch (err) {
            console.error(err);
            alert('Failed to upload photo.');
        }
    };

    if (!user) {
        return <div>Loading profile...</div>;
    }

    return (
        <div className="profile-dashboard">
            <div className="profile-header">
                <h2>User Profile</h2>
            </div>
            <div className="profile-card">
                <div className="profile-photo-section">
                    <div className="profile-photo-wrapper">
                        {user.photo ? (
                            <img src={user.photo} alt="User Profile" className="profile-image" />
                        ) : (
                            <FontAwesomeIcon icon={faUserCircle} className="default-avatar" />
                        )}
                        <label htmlFor="file-upload" className="upload-icon-btn">
                            <FontAwesomeIcon icon={faCamera} />
                        </label>
                        <input id="file-upload" type="file" onChange={handlePhotoChange} style={{ display: 'none' }} />
                    </div>
                    {photo && (
                        <div className="upload-controls">
                            <button onClick={handlePhotoUpload}>
                                <FontAwesomeIcon icon={faUpload} /> Upload Photo
                            </button>
                        </div>
                    )}
                </div>

                <div className="profile-info-section">
                    <div className="info-item">
                        <FontAwesomeIcon icon={faUserCircle} className="info-icon" />
                        <div className="info-text">
                            <h3>Name</h3>
                            <p>{user.name}</p>
                        </div>
                    </div>
                    <div className="info-item">
                        <FontAwesomeIcon icon={faEnvelope} className="info-icon" />
                        <div className="info-text">
                            <h3>Email</h3>
                            <p>{user.email}</p>
                        </div>
                    </div>
                    <div className="info-item">
                        <FontAwesomeIcon icon={faUserTag} className="info-icon" />
                        <div className="info-text">
                            <h3>Role</h3>
                            <p>{user.role}</p>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default Profile;
